PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, phone_hash TEXT, display_name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL REFERENCES users(id), display_name TEXT NOT NULL, provider_type TEXT NOT NULL, city TEXT NOT NULL, verification_level TEXT NOT NULL DEFAULT 'DECLARED', is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS catalog_items(id TEXT PRIMARY KEY, provider_id TEXT REFERENCES providers(id), kind TEXT NOT NULL CHECK(kind IN('SERVICE','PRODUCT','FORMATION')), title TEXT NOT NULL, description TEXT, body_zone TEXT, price_label TEXT, availability_status TEXT NOT NULL DEFAULT 'PLANNED', claim_risk TEXT NOT NULL DEFAULT 'LOW', is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS client_needs(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), service_query TEXT NOT NULL, body_zone TEXT, city TEXT NOT NULL, timing TEXT NOT NULL, budget_label TEXT, home_service INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY, client_user_id TEXT NOT NULL REFERENCES users(id), provider_id TEXT NOT NULL REFERENCES providers(id), catalog_item_id TEXT REFERENCES catalog_items(id), scheduled_at TEXT, status TEXT NOT NULL, agreed_price INTEGER, currency TEXT NOT NULL DEFAULT 'XAF', payment_requirement TEXT NOT NULL DEFAULT 'PAY_AFTER_SERVICE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_declarations(id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), method TEXT NOT NULL CHECK(method IN('CASH','MOMO_DIRECT','ORANGE_DIRECT','OTHER')), amount INTEGER NOT NULL, declared_by TEXT NOT NULL, counterparty_confirmed_at TEXT, provider_verified_at TEXT, external_reference TEXT, status TEXT NOT NULL DEFAULT 'DECLARED', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS loyalty_programs(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES providers(id), name TEXT NOT NULL, target_count INTEGER NOT NULL, reward_label TEXT NOT NULL, sponsor_name TEXT, stock_confirmed INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS loyalty_progress(id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES loyalty_programs(id), user_id TEXT NOT NULL REFERENCES users(id), confirmed_count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(program_id,user_id));
CREATE TABLE IF NOT EXISTS media_posts(id TEXT PRIMARY KEY, author_user_id TEXT NOT NULL REFERENCES users(id), provider_id TEXT REFERENCES providers(id), caption TEXT, media_type TEXT NOT NULL CHECK(media_type IN('PHOTO','VIDEO')), consent_scope TEXT NOT NULL, moderation_status TEXT NOT NULL DEFAULT 'PENDING', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS safety_missions(id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), owner_role TEXT NOT NULL, emergency_contact_name TEXT NOT NULL, emergency_contact_phone TEXT, status TEXT NOT NULL, expires_at TEXT, check_in_at TEXT, check_out_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_formulas(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES providers(id), product_name TEXT NOT NULL, formula_version TEXT NOT NULL, ingredients_declared_json TEXT NOT NULL, batch_code TEXT, manufactured_at TEXT, expires_at TEXT, risk_class TEXT NOT NULL DEFAULT 'COSMETIC', verification_status TEXT NOT NULL DEFAULT 'DECLARED', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS adverse_event_reports(id TEXT PRIMARY KEY, product_formula_id TEXT REFERENCES product_formulas(id), reporter_user_id TEXT REFERENCES users(id), severity TEXT NOT NULL, symptoms TEXT NOT NULL, onset_at TEXT, status TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_catalog_search ON catalog_items(kind,body_zone,is_active);
CREATE INDEX IF NOT EXISTS idx_needs_city_status ON client_needs(city,status,created_at);
CREATE INDEX IF NOT EXISTS idx_bookings_provider_time ON bookings(provider_id,scheduled_at,status);
